9|// Returns the median of the values in `samples`. For an even-length input
10|// the median is the mean of the two middle values after sorting. For an
11|// empty input the function returns 0.0.
12|double Median(std::vector<double> samples) {
13|    if (samples.empty()) return 0.0;
14|    std::sort(samples.begin(), samples.end());
15|    const std::size_t n = samples.size();
16|    if (n % 2 == 1) {
17|        return samples[n / 2];
18|    }
