37|                                  std::size_t num_buckets) {
38|    std::vector<double> out(2 * num_buckets, 0.0);
39|    if (values.empty() || num_buckets == 0) return out;
40|    const std::size_t n = values.size();
41|    const std::size_t per = n / num_buckets;
42|    const std::size_t extra = n % num_buckets;
43|    std::size_t cursor = 0;
44|    for (std::size_t b = 0; b < num_buckets; ++b) {
45|        const std::size_t size = per + (b < extra ? 1 : 0);
46|        const std::size_t lo = cursor;
47|        const std::size_t hi = cursor + size;
48|        if (lo < hi) {
